def hero():
    return '''<section class="home-hero"><div><p class="home-eyebrow"><i aria-hidden="true"></i> ALWAYS ON, ALWAYS GROWING</p><h1>让好生意被看见，<br>让<em>AI</em>持续运营。</h1><p class="home-lead">从一份清晰的企业主页，到持续更新的视频与图文。<br>营火让小企业也能拥有自己的AI运营团队。</p><div class="buttons"><a class="button" href="/register">开始使用营火 <span aria-hidden="true">↗</span></a><a class="button secondary" href="#discover">发现入驻企业 <span aria-hidden="true">↓</span></a></div><p class="home-note">企业公开主页<span>·</span>数字员工协作<span>·</span>多账号发布</p></div><aside class="home-visual" aria-label="产品能力示意"><div class="visual-head"><span>CAMPFIRE / 企业运营空间</span><span>能力概览</span></div><div class="visual-card">''' + BRAND_ICON + '''<h2>把你的好生意，<br>介绍给更多人。</h2><p>让企业信息清晰，让日常运营持续。</p><div class="visual-tags"><span>企业介绍</span><span>产品与服务</span><span>客户常见问题</span></div></div><div class="visual-footer"><div class="visual-row"><b>01</b><span>一份清晰的企业主页</span><span aria-hidden="true">↗</span></div><div class="visual-row"><b>02</b><span>一套持续的内容运营</span><span aria-hidden="true">↗</span></div><div class="visual-row"><b>03</b><span>一处看得见的数据反馈</span><span aria-hidden="true">↗</span></div></div></aside></section>'''


def benefits():
    icons = [
        '<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M7 13h5M7 16h9"/>',
        '<path d="m12 3 2.6 5.4 6 .9-4.3 4.2 1 6-5.3-2.8-5.3 2.8 1-6-4.3-4.2 6-.9L12 3Z"/>',
        '<path d="M4 20V4M4 20h17M9 16v-5M14 16V7M19 16v-8"/>',
    ]
    entries = [
        ('让客户更容易了解你', '用企业介绍、真实服务和常见问题，建立一个可公开访问、便于检索系统读取的企业主页。'),
        ('让内容运营持续发生', '数字员工协作策划与制作内容，利用企业素材，向已授权的抖音、视频号等账号发布。'),
        ('让每一步都有迹可循', '在工作台查看任务进度、平台作品数据和主页访问，用真实反馈帮助后续运营。'),
    ]
    cards = ''.join(f'<article class="benefit"><div class="benefit-top"><span class="benefit-icon"><svg viewBox="0 0 24 24" aria-hidden="true">{icon}</svg></span><small>0{i+1}</small></div><h3>{title}</h3><p>{description}</p></article>' for i, (icon, (title, description)) in enumerate(zip(icons, entries)))
    return '<section class="home-benefits"><div class="section-head"><div><p class="section-kicker">BUILT FOR SMALL BUSINESSES</p><h2>少一些运营琐事，<br>多一些生意的可能。</h2></div><p>把企业信息、内容制作和发布反馈连接起来。<br>你专注经营，营火协助你持续运营。</p></div><div class="benefit-grid">'+cards+'</div></section><section class="home-cta"><div><h2>为你的企业，点亮一簇营火。</h2><p>创建工作区，完善资料，从企业主页与第一个运营任务开始。</p></div><a class="button" href="/register">创建企业工作区 <span aria-hidden="true">↗</span></a></section>'


def footer():
    return '<footer><div class="footer-top"><div><a class="logo" href="/">'+BRAND_ICON+'营火AI</a><p>Always on, Always Growing.</p></div><div class="footer-links"><a href="/business">企业服务</a><a href="/about">关于营火</a><a href="/privacy">隐私说明</a><a href="/llms.txt">AI内容导航</a></div></div><div class="footer-bottom">营火AI · AI运营平台<span aria-hidden="true"> &nbsp; / &nbsp; </span>企业公开资料由对应企业维护并确认，服务详情与最近发布时间请见企业主页。</div></footer>'
